            discard: false,
            delay: false,
            filterCard: lib.filter.cardRecastable,
            filter(event, player) {
                const num = lib.suit.slice(0).removeArray(
                    get.discarded().map((card2) => get.suit(card2)).unique()
                ).length;
                return player.countCards("he") && num > 0;
            },
