            audio: "ext:永夜之境/audio:6",
            logAudio: index => (typeof index === "number" ? "ext:永夜之境/audio/xinxzhili" + index + ".mp3" : "ext:永夜之境/audio/xinxzhili" + get.rand(3, 4) + ".mp3"),
