                            if (newX === 2) {
                                player.changeSkin({ characterName: "xinx_feixiao" }, "xinx_feixiao_shadow2");

                            } else if (newX === 3) {
                                const targetSkin = Math.random() < 0.5 ? "xinx_feixiao_shadow4" : "xinx_feixiao_shadow5";
                                player.changeSkin({ characterName: "xinx_feixiao" }, targetSkin);
                            }
