                    let maxCharge = player.getMaxCharge();
                    num = Math.min(num, maxCharge - player.countMark("charge"));
                    var next = game.createEvent("addCharge", false);
                    next.player = this;
                    next.num = num;
                    next.log = log;
                    next.setContent("addCharge");
                    return next;
